/**
 * @name Unsafe pickle deserialization with user input
 * @description Untrusted data flowing to pickle.loads can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/pickle-deserialization-pytest
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PickleDeserializationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember(["loads", "load"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PickleDeserializationFlow = TaintTracking::Global<PickleDeserializationConfig>;
import PickleDeserializationFlow::PathGraph

from PickleDeserializationFlow::PathNode source, PickleDeserializationFlow::PathNode sink
where PickleDeserializationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe pickle deserialization from $@.", source.getNode(), "user input"

/**
 * @name Dynamic code execution and import in pytest
 * @description Using eval, exec, or __import__ with untrusted input can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/dynamic-code-pytest
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module DynamicCodeConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::builtin(["eval", "exec", "__import__"]).getACall() or
        call = API::moduleImport("importlib").getMember(["import_module"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module DynamicCodeFlow = TaintTracking::Global<DynamicCodeConfig>;
import DynamicCodeFlow::PathGraph

from DynamicCodeFlow::PathNode source, DynamicCodeFlow::PathNode sink
where DynamicCodeFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Dynamic code execution/import from $@.", source.getNode(), "user input"

/**
 * @name Path traversal in pytest file operations
 * @description Untrusted data flowing to file path operations can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-pytest
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // File open operations
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      // os.path.join with potential for traversal
      call = API::moduleImport("os.path").getMember("join").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      // Path construction
      call = API::moduleImport("pathlib").getMember("Path").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"
